// Pseudo: fetch KEK, generate data key, encrypt payload, store ciphertext and wrapped key
async function sealPayload(tenantId, payload, kms){
  const KEK = await kms.getKEK(tenantId);
  const DEK = crypto.getRandomValues(new Uint8Array(32));
  const wrappedDEK = await wrapKeyWithKEK(DEK, KEK);
  const ciphertext = await encrypt(payload, DEK);
  return { ciphertext, wrappedDEK };
}
```

